import {For,Show,createMemo,createSignal,onCleanup,onMount} from 'solid-js';
import {useQuery,useWorld} from '@diffusionstudio/koota-solid';
import {Computed,FrameRate,Name,Scene,sortByItemIndex} from '@diffusionstudio/runtime';
import {createImageEncoder} from '@diffusionstudio/encoder';
import {createCapture,useActiveScene,useEditor,useEngineContext} from '@/engine';
import {renderScene} from '@/context/render';
import {encodeStaticGif} from './static-gif';
import {TOKEN_KEY,formatIdFromSceneName,requiredOutputs,type BannermaticCampaign,type CampaignFormat} from './campaign';

type PublishArtifact={kind:'png'|'jpg'|'gif'|'video';mimeType:string;width:number;height:number;durationSec:number;dataBase64:string};
const nextFrame=()=>new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve())));
async function asBase64(bytes:Uint8Array|ArrayBuffer){const data=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);let binary='';for(let i=0;i<data.length;i+=32768)binary+=String.fromCharCode(...data.subarray(i,i+32768));return btoa(binary)}
async function rasterFromPng(png:Uint8Array,mimeType:string,quality=.9){const bitmap=await createImageBitmap(new Blob([png as BlobPart],{type:'image/png'})),canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;const ctx=canvas.getContext('2d',{willReadFrequently:true})!;if(mimeType==='image/jpeg'){ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height)}ctx.drawImage(bitmap,0,0);bitmap.close();if(mimeType==='image/gif')return new Blob([encodeStaticGif(ctx.getImageData(0,0,canvas.width,canvas.height)) as BlobPart],{type:'image/gif'});return new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error(`Could not encode ${mimeType}`)),mimeType,quality))}
async function boundedJpeg(png:Uint8Array,maxBytes:number){let last:Blob|null=null;for(const quality of [.92,.86,.8,.72,.64,.56,.48,.4,.32,.24]){last=await rasterFromPng(png,'image/jpeg',quality);if(!maxBytes||last.size<=maxBytes)return last}return last!}

export function CampaignProductionPanel(props:{campaign:BannermaticCampaign;onCampaign:(value:BannermaticCampaign)=>void}){
 const world=useWorld(),engine=useEngineContext(),editor=useEditor(),active=useActiveScene(),allScenes=useQuery(Scene);
 const scenes=createMemo(()=>[...allScenes()].filter(scene=>Boolean(formatIdFromSceneName(scene.get(Name)?.value))).sort(sortByItemIndex)),[open,setOpen]=createSignal(false),[busy,setBusy]=createSignal(false),[progress,setProgress]=createSignal(''),[error,setError]=createSignal('');
 let trigger!:HTMLButtonElement,panel!:HTMLElement;
 onMount(()=>{const pointer=(event:PointerEvent)=>{if(!open())return;const target=event.target as Node|null;if(target&&(trigger.contains(target)||panel?.contains(target)))return;setOpen(false)},key=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpen(false)};document.addEventListener('pointerdown',pointer,true);document.addEventListener('keydown',key);onCleanup(()=>{document.removeEventListener('pointerdown',pointer,true);document.removeEventListener('keydown',key)})});
 const activeFormat=createMemo(()=>{const id=formatIdFromSceneName(active()?.get(Name)?.value);return props.campaign.formats.find(format=>format.id===id)||null});
 const placements=(format:CampaignFormat)=>format.placementIds.map(id=>props.campaign.placements.find(item=>item.id===id)).filter(Boolean);
 const durationFor=(scene:any)=>{const frames=Number(scene.get(Computed)?.duration||0),fps=Number(world.get(FrameRate)?.value||30);return frames/fps};
 const captureFrame=async(scene:any,format:CampaignFormat)=>{const capture=await createCapture(world,scene,{mode:'offline-video'});try{const imageEncoder=await createImageEncoder(capture.world,{frames:[0],resolution:format.height*(Number(format.exportScale)===2?2:1)}),result=await imageEncoder.render();if(result.type!=='success')throw result.type==='error'?result.error:new Error('Frame render canceled');return result.data[0].png}finally{capture.dispose()}};
 const publishFormat=async(scene:any,format:CampaignFormat)=>{editor.activate(scene);await nextFrame();const scale=Number(format.exportScale)===2?2:1,width=format.width*scale,height=format.height*scale,outputs=requiredOutputs(props.campaign,format),png=await captureFrame(scene,format),durationSec=durationFor(scene),artifacts:PublishArtifact[]=[];const add=async(kind:PublishArtifact['kind'],mimeType:string,blob:Blob|Uint8Array)=>{const bytes=blob instanceof Uint8Array?blob:new Uint8Array(await blob.arrayBuffer());artifacts.push({kind,mimeType,width,height,durationSec,dataBase64:await asBase64(bytes)})};if(outputs.includes('png')||outputs.includes('html5')||!outputs.length)await add('png','image/png',png);if(outputs.includes('jpg')){const limits=placements(format).filter(p=>(p?.requirements?.exportType||p?.creativeType||'').toLowerCase().includes('jp')).map(p=>Number(p?.requirements?.maxZipKb||0)*1000).filter(Boolean);await add('jpg','image/jpeg',await boundedJpeg(png,limits.length?Math.min(...limits):0))}if(outputs.includes('gif')||outputs.includes('html5+gif'))await add('gif','image/gif',await rasterFromPng(png,'image/gif'));if(outputs.includes('video')){const limits=placements(format).filter(p=>String(p?.requirements?.exportType||p?.creativeType||'').toLowerCase().match(/video|mp4|webm|mov/)).map(p=>Number(p?.requirements?.maxZipKb||0)*1000).filter(Boolean),maxBytes=limits.length?Math.min(...limits):0,bitrate=maxBytes&&durationSec?Math.max(100_000,Math.floor(maxBytes*8*.82/Math.max(.25,durationSec))):2_000_000,result=await renderScene(engine,{scene,config:{format:'mp4',video:{codec:'avc',resolution:Math.min(width,height),bitrate},audio:{enabled:false}},source:'ui'});if(result.type!=='success'||!result.data)throw result.type==='error'?result.error:new Error('Video render canceled');await add('video','video/mp4',result.data)}const token=localStorage.getItem(TOKEN_KEY)||'',response=await fetch(`/api/campaigns/${encodeURIComponent(props.campaign.id)}/diffusion-publish`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json'},body:JSON.stringify({formatId:format.id,artifacts})}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Publish failed: ${response.status}`);props.onCampaign(data.campaign);return data};
 const run=async(all:boolean)=>{if(busy())return;setBusy(true);setError('');try{const queue=all?scenes().map(scene=>({scene,format:props.campaign.formats.find(format=>format.id===formatIdFromSceneName(scene.get(Name)?.value))})).filter(item=>item.format):activeFormat()?[{scene:active(),format:activeFormat()}]:[];if(!queue.length)throw new Error('No campaign format scene is active');for(let i=0;i<queue.length;i++){const item=queue[i] as {scene:any;format:CampaignFormat};setProgress(`${i+1}/${queue.length} · ${item.format.size}`);await publishFormat(item.scene,item.format)}setProgress(`Published ${queue.length} format${queue.length===1?'':'s'}`)}catch(value){setError(value instanceof Error?value.message:String(value))}finally{setBusy(false)}};
 return <><button ref={trigger} class="bm-campaign-pill" aria-haspopup="dialog" aria-expanded={open()} title="Campaign formats and delivery" onClick={()=>setOpen(value=>!value)}><span>B</span><b>{props.campaign.name}</b><em>{props.campaign.formats.length} formats</em></button><Show when={open()}><aside ref={panel} class="bm-campaign-panel" role="dialog" aria-label="Campaign formats and delivery"><header><div><small>CAMPAIGN PRODUCTION</small><h2>{props.campaign.name}</h2><p>Select a format to edit it on canvas. Publish creates the files required by its placements.</p></div><button aria-label="Close campaign production" onClick={()=>setOpen(false)}>×</button></header><div class="bm-campaign-versions"><span>Media plan v{props.campaign.mediaPlanVersion||0}</span><span>Creative v{props.campaign.creativeVersion||0}</span></div><div class="bm-campaign-formats"><For each={props.campaign.formats}>{format=>{const scene=()=>scenes().find(item=>formatIdFromSceneName(item.get(Name)?.value)===format.id),selected=()=>activeFormat()?.id===format.id,status=()=>!scene()?'unavailable':format.creativeState==='missing'?'not published':format.creativeState;return <button disabled={!scene()} classList={{active:selected()}} onClick={()=>{const target=scene();if(target){editor.activate(target);setOpen(false)}}}><span><b>{format.size}</b><small>{placements(format).length} placement{placements(format).length===1?'':'s'}</small></span><em>{requiredOutputs(props.campaign,format).join(' + ').toUpperCase()}</em><i class={scene()?format.creativeState:'missing'}>{status()}</i></button>}}</For></div><Show when={activeFormat()}>{format=><section class="bm-campaign-requirements"><h3>{format().size} delivery</h3><For each={placements(format())}>{placement=><div><span><b>{placement?.platform}</b><small>{placement?.placement}</small></span><em>{String(placement?.requirements?.exportType||placement?.creativeType||'HTML5').toUpperCase()} · {placement?.requirements?.maxZipKb?`≤${placement.requirements.maxZipKb} KB`:'weight —'} · {placement?.requirements?.clickUrl?'click ✓':'click —'}</em></div>}</For></section>}</Show>{error()&&<p class="bm-campaign-error">{error()}</p>}{progress()&&<p class="bm-campaign-progress">{progress()}</p>}<footer><a href={`/?campaign=${encodeURIComponent(props.campaign.id)}`}>Back to campaign</a><button disabled={busy()||!activeFormat()} onClick={()=>void run(false)}>Publish format</button><button class="primary" disabled={busy()||!scenes().length} onClick={()=>void run(true)}>{busy()?'Rendering…':'Publish all formats'}</button></footer></aside></Show></>
}
